namespace AdielSystem.Infrastructure.Quotations;

public sealed class QuotationRepository(NpgsqlDataSource dataSource) : IQuotationRepository
{
    private const decimal VatRate = 0.12m;
    private static bool? hasDiscountColumns;

    public async Task<QuotationPageDto> ListAsync(string search, string? status, bool archivedOnly, int page, int pageSize, CancellationToken token)
    {
        await using var connection = await dataSource.OpenConnectionAsync(token);
        const string where = "deleted_at is null and (@archived_only = (archived_at is not null)) and (@status='' or status=@status) and (@search='' or quotation_number ilike @search or client_name ilike @search or subject ilike @search or project_location ilike @search)";
        var ids = new List<Guid>();
        await using (var command = connection.CreateCommand())
        {
            command.CommandText = $"select id from public.quotations where {where} order by quotation_date desc,created_at desc limit @limit offset @offset";
            AddListParameters(command, search, status, archivedOnly, page, pageSize);
            await using var reader = await command.ExecuteReaderAsync(token);
            while (await reader.ReadAsync(token)) ids.Add(reader.GetGuid(0));
        }
        var items = new List<QuotationDto>();
        foreach (var id in ids) items.Add(await RequiredAsync(connection, null, id, token));
        await using var count = connection.CreateCommand(); count.CommandText = $"select count(*) from public.quotations where {where}"; AddListParameters(count, search, status, archivedOnly, page, pageSize);
        return new(items, page, pageSize, (long)(await count.ExecuteScalarAsync(token) ?? 0L));
    }

    public async Task<QuotationDto?> GetAsync(Guid id, CancellationToken token) { await using var connection = await dataSource.OpenConnectionAsync(token); return await ReadAsync(connection, null, id, token); }

    public Task<QuotationDto> CreateAsync(SaveQuotationRequest request, string quotationNumber, CurrentUser actor, CancellationToken token) => ExecuteAsync(async (connection, transaction) =>
    {
        var client = await ResolveClientAsync(connection, transaction, request, token);
        var lines = await ResolveLinesAsync(connection, transaction, request.Lines, token);
        var totals = Calculate(lines, request.Charges, request.VatEnabled, request.DiscountType, request.DiscountValue, request.DiscountLabel);
        var hasDiscount = await HasDiscountColumnsAsync(connection, transaction, token);
        if (!hasDiscount && totals.Discount > 0) throw new RequestValidationException("Apply migration 20261031000000_quotation_discounts.sql before saving quotation discounts.");
        var id = Guid.NewGuid(); var status = IsSubmit(request) ? "For Approval" : "Draft";
        await using (var command = connection.CreateCommand()) { command.Transaction = transaction; command.CommandText = hasDiscount ? "insert into public.quotations (id,quotation_number,quotation_date,client_id,client_name,contact_id,contact_person,subject,project_location,lead_time,notes,terms,subtotal_amount,discount_type,discount_value,discount_amount,vat_enabled,vat_rate,vat_amount,total_amount,estimated_profit,status,submitted_at,submitted_by,created_by,updated_by) values (@id,@number,@date,@client_id,@client_name,@contact_id,@contact_person,@subject,@location,@lead_time,@notes,@terms,@subtotal,@discount_type,@discount_value,@discount_amount,@vat_enabled,@vat_rate,@vat,@total,@profit,@status,case when @status='For Approval' then now() end,case when @status='For Approval' then @actor end,@actor,@actor)" : "insert into public.quotations (id,quotation_number,quotation_date,client_id,client_name,contact_id,contact_person,subject,project_location,lead_time,notes,terms,subtotal_amount,vat_enabled,vat_rate,vat_amount,total_amount,estimated_profit,status,submitted_at,submitted_by,created_by,updated_by) values (@id,@number,@date,@client_id,@client_name,@contact_id,@contact_person,@subject,@location,@lead_time,@notes,@terms,@subtotal,@vat_enabled,@vat_rate,@vat,@total,@profit,@status,case when @status='For Approval' then now() end,case when @status='For Approval' then @actor end,@actor,@actor)"; AddHeader(command, id, quotationNumber, request, client, totals, status, actor.Id, hasDiscount); await command.ExecuteNonQueryAsync(token); }
        await ReplaceChildrenAsync(connection, transaction, id, lines, request.Charges, token);
        await AuditAsync(connection, transaction, id, "Created", quotationNumber, $"Quotation created for {client.Name}.", status, totals.Total, actor, token);
        return await RequiredAsync(connection, transaction, id, token);
    }, token);

    public Task<QuotationDto> UpdateAsync(Guid id, SaveQuotationRequest request, CurrentUser actor, CancellationToken token) => ExecuteAsync(async (connection, transaction) =>
    {
        var existing = await RequiredAsync(connection, transaction, id, token);
        if (existing.Status is "Approved" or "Voided") throw new ResourceConflictException("Approved or voided quotations cannot be edited.");
        var client = await ResolveClientAsync(connection, transaction, request, token);
        var lines = await ResolveLinesAsync(connection, transaction, request.Lines, token); var totals = Calculate(lines, request.Charges, request.VatEnabled, request.DiscountType, request.DiscountValue, request.DiscountLabel); var status = IsSubmit(request) ? "For Approval" : "Draft";
        var hasDiscount = await HasDiscountColumnsAsync(connection, transaction, token);
        if (!hasDiscount && totals.Discount > 0) throw new RequestValidationException("Apply migration 20261031000000_quotation_discounts.sql before saving quotation discounts.");
        await using (var command = connection.CreateCommand()) { command.Transaction = transaction; command.CommandText = hasDiscount ? "update public.quotations set quotation_date=@date,client_id=@client_id,client_name=@client_name,contact_id=@contact_id,contact_person=@contact_person,subject=@subject,project_location=@location,lead_time=@lead_time,notes=@notes,terms=@terms,subtotal_amount=@subtotal,discount_type=@discount_type,discount_value=@discount_value,discount_amount=@discount_amount,vat_enabled=@vat_enabled,vat_rate=@vat_rate,vat_amount=@vat,total_amount=@total,estimated_profit=@profit,status=@status,submitted_at=case when @status='For Approval' then coalesce(submitted_at,now()) end,submitted_by=case when @status='For Approval' then @actor end,rejection_reason=null,rejected_at=null,rejected_by=null,updated_by=@actor where id=@id and archived_at is null and deleted_at is null and version=@version returning id" : "update public.quotations set quotation_date=@date,client_id=@client_id,client_name=@client_name,contact_id=@contact_id,contact_person=@contact_person,subject=@subject,project_location=@location,lead_time=@lead_time,notes=@notes,terms=@terms,subtotal_amount=@subtotal,vat_enabled=@vat_enabled,vat_rate=@vat_rate,vat_amount=@vat,total_amount=@total,estimated_profit=@profit,status=@status,submitted_at=case when @status='For Approval' then coalesce(submitted_at,now()) end,submitted_by=case when @status='For Approval' then @actor end,rejection_reason=null,rejected_at=null,rejected_by=null,updated_by=@actor where id=@id and archived_at is null and deleted_at is null and version=@version returning id"; AddHeader(command, id, existing.QuotationNumber, request, client, totals, status, actor.Id, hasDiscount); command.Parameters.AddWithValue("version", request.Version!.Value); if (await command.ExecuteScalarAsync(token) is null) throw Stale(); }
        await ReplaceChildrenAsync(connection, transaction, id, lines, request.Charges, token);
        await AuditAsync(connection, transaction, id, "Updated", existing.QuotationNumber, "Quotation details, lines and charges were updated.", status, totals.Total, actor, token);
